class Solution {
    public String[] spellchecker(String[] wordlist,String[] queries){
        Set<String> exact=new HashSet<>();
        Map<String,String> lower=new HashMap<>(),vowel=new HashMap<>();
        for(String word:wordlist){
            exact.add(word);
            String normalized=word.toLowerCase();
            lower.putIfAbsent(normalized,word);
            vowel.putIfAbsent(mask(normalized),word);
        }
        String[] answer=new String[queries.length];
        for(int i=0;i<queries.length;i++){
            String query=queries[i],normalized=query.toLowerCase();
            if(exact.contains(query))answer[i]=query;
            else if(lower.containsKey(normalized))answer[i]=lower.get(normalized);
            else answer[i]=vowel.getOrDefault(mask(normalized),"");
        }
        return answer;
    }
    private String mask(String word){
        return word.replaceAll("[aeiou]","*");
    }
}

code.kotlin:
class Solution {
    fun spellchecker(wordlist:Array<String>,queries:Array<String>):Array<String>{
        val exact=wordlist.toHashSet();
        val lower=mutableMapOf<String,String>();
        val vowel=mutableMapOf<String,String>();
        fun mask(word:String):String{
            return word.map{
                if(it in "aeiou")'*' else it
            }.joinToString("")
        };
        for(word in wordlist){
            val normalized=word.lowercase();
            lower.putIfAbsent(normalized,word);
            vowel.putIfAbsent(mask(normalized),word)
        };
        return Array(queries.size){
            i->val query=queries[i];
            val normalized=query.lowercase();
            when{
                query in exact->query;
                normalized in lower->lower[normalized]!!;
                else->vowel[mask(normalized)]?:""
            }
        }
    }
}

